    private bindEvents(): void {
        this.analyzeBtn.addEventListener('click', () => this.analyzeProject());
        this.gitUriInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') this.analyzeProject();
        });
        this.callGraphFilterBtn?.addEventListener('click', () => this.toggleCallGraphFilter());
        this.couplingGraphFilterBtn?.addEventListener('click', () => this.toggleCouplingGraphFilter());
        this.dendrogramFilterBtn?.addEventListener('click', () => this.toggleDendrogramFilter());
        this.callGraphFullscreenBtn?.addEventListener('click', () => this.openFullscreen('call'));
        this.couplingGraphFullscreenBtn?.addEventListener('click', () => this.openFullscreen('coupling'));
        this.dendrogramFullscreenBtn?.addEventListener('click', () => this.openFullscreen('dendrogram'));
        
        // Bouton de test pour le dendrogramme (développement)
        const testBtn = document.createElement('button');
        testBtn.textContent = 'Test Dendrogramme';
        testBtn.style.position = 'fixed';
        testBtn.style.top = '10px';
        testBtn.style.right = '10px';
        testBtn.style.zIndex = '1000';
        testBtn.addEventListener('click', () => {
            const testData = this.createTestDendrogram();
            this.createSVGDendrogram(testData, this.dendrogramGraph);
        });
        document.body.appendChild(testBtn);
        this.fullscreenCloseBtn?.addEventListener('click', () => this.closeFullscreen());
        
        // Fermer le modal en cliquant sur l'arrière-plan
        this.fullscreenModal?.addEventListener('click', (e) => {
            if (e.target === this.fullscreenModal) {
                this.closeFullscreen();
            }
        });
        
        // Fermer avec la touche Escape
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.currentFullscreenGraph) {
                this.closeFullscreen();
            }
        });
    }

    private showLoader(): void {
        this.loader.classList.remove('hidden');
        this.errorDiv.classList.add('hidden');
        this.results.classList.add('hidden');
        this.analyzeBtn.disabled = true;
    }

    private hideLoader(): void {
        this.loader.classList.add('hidden');
        this.analyzeBtn.disabled = false;
    }

    private showError(message: string): void {
        this.errorDiv.textContent = message;
        this.errorDiv.classList.remove('hidden');
    }

    private showResults(): void {
        this.results.classList.remove('hidden');
    }

    private async analyzeProject(): Promise<void> {
        const gitUri = this.gitUriInput.value.trim();
        if (!gitUri) {
            this.showError('Veuillez saisir une URL Git valide');
            return;
        }

        this.showLoader();

        try {
            const response = await fetch('http://localhost:8090/api/analyses/git', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ uriGit: gitUri })
            });

            if (!response.ok) {
                throw new Error(`Erreur HTTP: ${response.status}`);
            }

            const data: AnalysisResponse = await response.json();
            this.currentAnalysisData = data;
            this.basePackage = data.basePackage || '';
            this.displayResults(data);
            this.showResults();
            this.updateFilterButtons();
        } catch (error) {
            this.showError(`Erreur lors de l'analyse: ${error instanceof Error ? error.message : 'Erreur inconnue'}`);
        } finally {
            this.hideLoader();
        }
    }

    private displayResults(data: AnalysisResponse): void {
        this.displayMetrics(data.metricsDto);
        this.displayCallGraph(data.graphDTO);
        this.displayCouplingGraph(data.treeCoupling);
    }

    private displayMetrics(metrics: MetricsDto): void {
        // Affichage des cartes métriques
        this.metricsCards.innerHTML = '';
        Object.entries(metrics).forEach(([key, value]) => {
            const card = document.createElement('div');
            card.className = 'metric-card';
            card.innerHTML = `
                <h3>${this.formatMetricName(key)}</h3>
                <div class="metric-value">${value}</div>
            `;
            this.metricsCards.appendChild(card);
        });

        // Résumé textuel
        const totalMetrics = Object.keys(metrics).length;
        const avgValue = Object.values(metrics).reduce((a, b) => a + b, 0) / totalMetrics;
        this.metricsSummary.innerHTML = `
            <div class="summary">
                <p><strong>Résumé:</strong> ${totalMetrics} métriques analysées avec une valeur moyenne de ${avgValue.toFixed(2)}</p>
            </div>
        `;
    }

    private formatMetricName(name: string): string {
        return name.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase());
    }

