    private convertAdjacencyListToCytoscape(adjacencyList: { [key: string]: any[] }): any[] {
        const elements: any[] = [];
        const nodes = new Set<string>();

        // Collecter tous les nœuds avec filtrage
        Object.keys(adjacencyList).forEach(source => {
            if (this.shouldIncludeInCallGraph(source)) {
                nodes.add(source);
            }
            adjacencyList[source].forEach(edge => {
                if (edge.calleeSignature && this.shouldIncludeInCallGraph(edge.calleeSignature)) {
                    if (this.shouldIncludeInCallGraph(source)) {
                        nodes.add(edge.calleeSignature);
                    }
                }
            });
        });

        // Ajouter les nœuds avec des labels simplifiés
        nodes.forEach(node => {
            const simplifiedLabel = this.simplifyMethodSignature(node);
            elements.push({
                data: { 
                    id: node, 
                    label: simplifiedLabel,
                    fullSignature: node
                }
            });
        });

        // Ajouter les arêtes avec filtrage
        Object.entries(adjacencyList).forEach(([source, edges]) => {
            if (this.shouldIncludeInCallGraph(source)) {
                edges.forEach(edge => {
                    if (edge.calleeSignature && this.shouldIncludeInCallGraph(edge.calleeSignature)) {
                        elements.push({
                            data: { 
                                id: `${source}-${edge.calleeSignature}`,
                                source: source,
                                target: edge.calleeSignature,
                                type: edge.type
                            }
                        });
                    }
                });
            }
        });

        return elements;
    }

    private simplifyMethodSignature(signature: string): string {
        // Extraire le nom de la classe et de la méthode
        const parts = signature.split('#');
        if (parts.length === 2) {
            const className = parts[0].split('.').pop() || parts[0];
            const methodPart = parts[1].split('(')[0];
            return `${className}.${methodPart}`;
        }
        // Fallback pour les signatures sans #
        const lastDot = signature.lastIndexOf('.');
        if (lastDot > 0) {
            return signature.substring(lastDot + 1);
        }
        return signature;
    }

    private convertCouplingToCytoscape(couplingEdges: CouplingEdge[]): any[] {
        const elements: any[] = [];
        const nodes = new Set<string>();

        // Collecter tous les nœuds avec filtrage
        couplingEdges.forEach(edge => {
            if (this.shouldIncludeInCouplingGraph(edge.classA)) {
                nodes.add(edge.classA);
            }
            if (this.shouldIncludeInCouplingGraph(edge.classB)) {
                nodes.add(edge.classB);
            }
        });

        // Ajouter les nœuds avec couplage
        nodes.forEach(node => {
            const nodeCoupling = couplingEdges
                .filter(e => e.classA === node || e.classB === node)
                .reduce((sum, e) => sum + e.coupling, 0);
            
            const simplifiedLabel = this.simplifyClassName(node);
            
            elements.push({
                data: { 
                    id: node, 
                    label: simplifiedLabel,
                    fullName: node,
                    coupling: nodeCoupling
                }
            });
        });

        // Ajouter les arêtes bidirectionnelles (éviter les doublons)
        const processedPairs = new Set<string>();
        couplingEdges.forEach(edge => {
            // Ne garder que les arêtes où les deux classes passent le filtre
            if (this.shouldIncludeInCouplingGraph(edge.classA) && this.shouldIncludeInCouplingGraph(edge.classB)) {
                const pairKey = [edge.classA, edge.classB].sort().join('-');
                if (!processedPairs.has(pairKey)) {
                    processedPairs.add(pairKey);
                    const couplingPercentage = Math.round(edge.coupling * 100);
                    elements.push({
                        data: {
                            id: `${edge.classA}-${edge.classB}`,
                            source: edge.classA,
                            target: edge.classB,
                            coupling: edge.coupling,
                            nbrOfLink: edge.nbrOfLink,
                            label: `${couplingPercentage}%`
                        }
                    });
                }
            }
        });

        return elements;
    }

    private simplifyClassName(className: string): string {
        // Extraire juste le nom de la classe sans le package complet
        const parts = className.split('.');
        return parts[parts.length - 1] || className;
    }

    private toggleCallGraphFilter(): void {
        this.callGraphFilterActive = !this.callGraphFilterActive;
        this.updateFilterButtons();
        if (this.currentAnalysisData) {
            this.displayCallGraph(this.currentAnalysisData.graphDTO);
        }
    }

    private toggleCouplingGraphFilter(): void {
        this.couplingGraphFilterActive = !this.couplingGraphFilterActive;
        this.updateFilterButtons();
        if (this.currentAnalysisData) {
            this.displayCouplingGraph(this.currentAnalysisData.treeCoupling);
        }
    }

    private updateFilterButtons(): void {
        if (this.callGraphFilterBtn) {
            this.callGraphFilterBtn.classList.toggle('active', this.callGraphFilterActive);
            this.callGraphFilterBtn.textContent = this.callGraphFilterActive 
                ? `Afficher tout (actuellement: ${this.basePackage}*)` 
                : 'Filtrer par package de base';
        }
        if (this.couplingGraphFilterBtn) {
            this.couplingGraphFilterBtn.classList.toggle('active', this.couplingGraphFilterActive);
            this.couplingGraphFilterBtn.textContent = this.couplingGraphFilterActive 
                ? `Afficher tout (actuellement: ${this.basePackage}*)` 
                : 'Filtrer par package de base';
        }
        if (this.dendrogramFilterBtn) {
            this.dendrogramFilterBtn.classList.toggle('active', this.dendrogramFilterActive);
            this.dendrogramFilterBtn.textContent = this.dendrogramFilterActive 
                ? `Afficher tout (actuellement: ${this.basePackage}*)` 
                : 'Filtrer par package de base';
        }
    }

    private shouldIncludeInCallGraph(signature: string): boolean {
        if (!this.callGraphFilterActive || !this.basePackage) {
            return true;
        }
        return signature.startsWith(this.basePackage);
    }

    private shouldIncludeInCouplingGraph(className: string): boolean {
        if (!this.couplingGraphFilterActive || !this.basePackage) {
            return true;
        }
        return className.startsWith(this.basePackage);
    }

    private shouldIncludeInDendrogramGraph(className: string): boolean {
        if (!this.dendrogramFilterActive || !this.basePackage) {
            return true;
        }
        return className.startsWith(this.basePackage);
    }

    private toggleDendrogramFilter(): void {
        this.dendrogramFilterActive = !this.dendrogramFilterActive;
        this.updateFilterButtons();
        if (this.currentAnalysisData && this.currentAnalysisData.rootDendro) {
            this.displayDendrogramGraph(this.currentAnalysisData.rootDendro);
        }
    }

    private openFullscreen(graphType: 'call' | 'coupling' | 'dendrogram'): void {
        this.currentFullscreenGraph = graphType;
        this.fullscreenModal.classList.remove('hidden');
        
        if (graphType === 'call') {
            this.fullscreenTitle.textContent = 'Graphe d\'Appels - Plein Écran';
            if (this.currentAnalysisData) {
                this.displayCallGraphInContainer(this.currentAnalysisData.graphDTO, this.fullscreenGraph);
            }
        } else if (graphType === 'coupling') {
            this.fullscreenTitle.textContent = 'Graphe de Couplage - Plein Écran';
            if (this.currentAnalysisData) {
                this.displayCouplingGraphInContainer(this.currentAnalysisData.treeCoupling, this.fullscreenGraph);
            }
        } else if (graphType === 'dendrogram') {
            this.fullscreenTitle.textContent = 'Dendrogramme - Plein Écran';
            if (this.currentAnalysisData && this.currentAnalysisData.rootDendro) {
                this.displayDendrogramGraphInContainer(this.currentAnalysisData.rootDendro, this.fullscreenGraph);
            }
        }
    }

    private closeFullscreen(): void {
        this.fullscreenModal.classList.add('hidden');
        this.currentFullscreenGraph = null;
        this.fullscreenGraph.innerHTML = '';
    }

