    private displayDendrogramGraphInContainer(rootDendro: DendroNode, container: HTMLElement): void {
        container.innerHTML = '';
        
        const elements = this.convertDendrogramToCytoscape(rootDendro);
        
        cytoscape({
            container: container,
            elements: elements,
            style: [
                {
                    selector: 'node[type="leaf"]',
                    style: {
                        'background-color': '#27ae60',
                        'label': 'data(label)',
                        'text-valign': 'center',
                        'text-halign': 'center',
                        'color': '#2c3e50',
                        'font-size': '12px',
                        'font-weight': 'bold',
                        'text-outline-width': 2,
                        'text-outline-color': '#fff',
                        'text-outline-opacity': 0.8,
                        'width': '80px',
                        'height': '80px',
                        'border-width': 2,
                        'border-color': '#229954',
                        'text-wrap': 'wrap',
                        'text-max-width': '75px',
                        'shape': 'ellipse'
                    }
                },
                {
                    selector: 'node[type="internal"]',
                    style: {
                        'background-color': (ele: any) => {
                            const coupling = ele.data('coupling') || 0;
                            const intensity = Math.min(coupling, 1);
                            return `rgb(${Math.round(155 + (52 - 155) * intensity)}, ${Math.round(89 + (152 - 89) * intensity)}, ${Math.round(182 + (219 - 182) * intensity)})`;
                        },
                        'label': 'data(label)',
                        'text-valign': 'center',
                        'text-halign': 'center',
                        'color': '#fff',
                        'font-size': '10px',
                        'font-weight': 'bold',
                        'text-outline-width': 1,
                        'text-outline-color': '#2c3e50',
                        'text-outline-opacity': 0.8,
                        'width': '50px',
                        'height': '50px',
                        'border-width': 2,
                        'border-color': '#8e44ad',
                        'shape': 'diamond'
                    }
                },
                {
                    selector: 'edge',
                    style: {
                        'width': 3,
                        'line-color': '#2c3e50',
                        'curve-style': 'segments',
                        'segment-distances': [0.5],
                        'segment-weights': [0.5],
                        'edge-distances': 'node-position',
                        'source-endpoint': 'outside-to-node',
                        'target-endpoint': 'outside-to-node'
                    }
                }
            ],
            layout: {
                name: 'preset',
                animate: true,
                animationDuration: 1500,
                fit: true,
                padding: 80
            }
        });
    }
